%%% ------------------ Test the rtl initially with one offset only
%(Test the correlation function only)
preamble_vector = 1-2*preamble_vector;                 % ensure ±1 if originally 0/1
preamble_fixed = int16(preamble_vector * 2^14); % Q14 format 
samples_0 = MFOut_truncated(1:OSR:end);    % take the first samples for now (0th) to test the correlator function

% Pass preamble fixed vector
fid = fopen('PreambleFixedVecotr.txt','w'); 
data = preamble_fixed;
fprintf(fid, '%04X\n', typecast(data,'uint16'));
% Pass samples of offset 0 
fid = fopen('PreambTest_firstOffset.txt','w');
data = int16(samples_0);                   % quantize to 16-bit
fprintf(fid, '%04X\n', typecast(data,'uint16'));
fclose(fid);

% Correlate samples of offset 0 <-> with preamble
samples0_extend = [zeros(N-1,1); samples_0; zeros(N-1,1)];
length_corr = length(samples_0) + N -1;     % no. of corr outputs (same like conv N1+N2-1)
    for k = 1:length_corr      
        corr_0(k) = sum(samples0_extend(k:k+N-1) .* double(preamble_fixed)); 	% like I shift right each cycle
    end 
    corr_0 = reshape(corr_0,length(corr_0),1); 
    max_corr = max(corr_0); 
    
% [corr_0;zeros(41-25,1)] == xcorr(preamble_fixed,samples_0) % ture implementation 
% plot(corr_0); % has a peak at 263 (32/4+255) = the true shift.

%%% -------------- Now the 4 offsets : search for max offset & frame start
best_metric = -inf;
best_offset = 0;
best_index = 0;

% Pass samples of offset 0 
fid = fopen('SamplerInputTest.txt','w');    % MfOutTruncated
data = int16(MFOut_truncated);                   % quantize to 16-bit
fprintf(fid, '%04X\n', typecast(data,'uint16'));
fclose(fid);

for offset = 0:OSR-1
    % Downsample with this phase
    samples_offset = MFOut_truncated(offset+1:OSR:end);
    
    samples_extend = [zeros(N-1,1); samples_offset; zeros(N-1,1)];
    length_corr = length(samples_offset) + N - 1;     % no. of corr outputs (same like conv N1+N2-1)
    
    for k = 1:length_corr      
        corr(k) = sum(samples_extend(k:k+N-1) .* double(preamble_fixed));
    end 
    corr = reshape(corr,length(corr),1);
     %figure; plot(corr);               % plot the 4 offset separately
     plot(corr); hold on;      % plot for 4 offsets merged 
                                        % comment the previous first
    % Find peak
    [peak, idx] = max(abs(corr));
    %peaks(offset+1) = peak; 
    %indecies(offset+1) = idx; 
    % Keep best
    if peak > best_metric
        best_metric = peak;
        best_offset = offset;
        best_index = idx;
    end
end



hold on; plot((0.7*best_metric)*ones(1,length(corr))); hold off;
 		% 0.7 of the max peak is the threshold values (to account for channel errors)

% ------------ Truncation in correlation output (based on max corr 
max_val = best_metric;      % consider max value out of 4 offsets 
% in rtl it is a result of successive sum (Q2.14(Preamb) * Q4.12(MF)) = resulted in Q14.26
max_val = max_val/2^26;     % throw out all fractional bits to know the integer part value
                            % to provide approbriate width for it of the 16-bit registers 

test = max_val > 2^9;         % more than 10 bits. 
testt = max_val < 2^10-1;      % so it needs at least 11 bits (12 for more safety maybe)
                              % so I kept for fractional just 4 bits (if 12) out of
                              % the resulted 26 for it -> so throw most 22 right bits
    
% Now, I can make the correct truncation
    %(based on biggest output value over all calculations)                              
corr0_truncated = int16(bitshift(int64(corr_0), -22));

% test the rtl (Correlation_Calc module) - truncated 
corr0_truncated =[zeros(9,1);corr0_truncated];       % to match with rtl output (pipeline latency) 
rtl_output = readmatrix('RTLcorrelation_output.txt'); 
%error_initially = corr0_truncated - int16(rtl_output);    % no errors Alhmdoulilah                          
[maxOut, maxOffset] = max(corr0_truncated);     



%------------- Threshold for rtl detection
pream_dtect_th = 0.7 * max(corr0_truncated); 







